+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * Filter applied by {@link CustomerRepository}.
+ *
+ * @param name     whitespace separated terms; each must occur in the first or last name,
+ *                 ignoring case and accents. {@code null} or blank matches everything
+ * @param statuses accepted statuses; {@code null} or empty matches every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        List<String> terms = terms();
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String first = fold(customer.firstName());
+        String last = fold(customer.lastName());
+        return terms.stream().allMatch(t -> first.contains(t) || last.contains(t));
+    }
+
+    private List<String> terms() {
+        String folded = fold(name).trim();
+        return folded.isEmpty() ? List.of() : List.of(folded.split("\\s+"));
+    }
+
+    private static String fold(String s) {
+        return Normalizer.normalize(s, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
